CREATE INDEX IF NOT EXISTS `records_landed_instant_idx` ON `records` (`workspace_id`,CASE WHEN json_type(`data`, '$.integrated.time.instant') = 'text' AND json_extract(`data`, '$.integrated.time.instant') GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]*' AND (json_extract(`data`, '$.integrated.time.instant') GLOB '*Z' OR json_extract(`data`, '$.integrated.time.instant') GLOB '*[+-][0-9][0-9]:[0-9][0-9]') THEN unixepoch(json_extract(`data`, '$.integrated.time.instant'), 'subsec') END,`id`) WHERE `kind` = 'merge_entry' AND `deleted_at` IS NULL AND json_extract(`data`, '$.state') = 'merged';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS `records_landed_instant_repo_idx` ON `records` (`workspace_id`,json_extract(`data`, '$.changeset.root'),CASE WHEN json_type(`data`, '$.integrated.time.instant') = 'text' AND json_extract(`data`, '$.integrated.time.instant') GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]*' AND (json_extract(`data`, '$.integrated.time.instant') GLOB '*Z' OR json_extract(`data`, '$.integrated.time.instant') GLOB '*[+-][0-9][0-9]:[0-9][0-9]') THEN unixepoch(json_extract(`data`, '$.integrated.time.instant'), 'subsec') END,`id`) WHERE `kind` = 'merge_entry' AND `deleted_at` IS NULL AND json_extract(`data`, '$.state') = 'merged';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS `records_landed_lane_idx` ON `records` (`workspace_id`,CASE WHEN json_type(`data`, '$.changeset.root') = 'text' THEN json_extract(`data`, '$.changeset.root') || CASE WHEN json_extract(`data`, '$.documents') IS NULL THEN '' ELSE ' documents' END END,CASE WHEN json_type(`data`, '$.integrated.time.instant') = 'text' AND json_extract(`data`, '$.integrated.time.instant') GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]*' AND (json_extract(`data`, '$.integrated.time.instant') GLOB '*Z' OR json_extract(`data`, '$.integrated.time.instant') GLOB '*[+-][0-9][0-9]:[0-9][0-9]') THEN unixepoch(json_extract(`data`, '$.integrated.time.instant'), 'subsec') END,`id`) WHERE `kind` = 'merge_entry' AND `deleted_at` IS NULL AND json_extract(`data`, '$.state') = 'merged';--> statement-breakpoint
CREATE INDEX IF NOT EXISTS `records_landed_repo_lane_idx` ON `records` (`workspace_id`,json_extract(`data`, '$.changeset.root'),CASE WHEN json_type(`data`, '$.changeset.root') = 'text' THEN json_extract(`data`, '$.changeset.root') || CASE WHEN json_extract(`data`, '$.documents') IS NULL THEN '' ELSE ' documents' END END,CASE WHEN json_type(`data`, '$.integrated.time.instant') = 'text' AND json_extract(`data`, '$.integrated.time.instant') GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]T[0-9][0-9]:[0-9][0-9]:[0-9][0-9]*' AND (json_extract(`data`, '$.integrated.time.instant') GLOB '*Z' OR json_extract(`data`, '$.integrated.time.instant') GLOB '*[+-][0-9][0-9]:[0-9][0-9]') THEN unixepoch(json_extract(`data`, '$.integrated.time.instant'), 'subsec') END,`id`) WHERE `kind` = 'merge_entry' AND `deleted_at` IS NULL AND json_extract(`data`, '$.state') = 'merged';
